/**
 * Ultra-fast optimized Lucide icons for Mapa da Bíblia
 */
(function(global) {
  const iconDefinitions = {
    'book': [
      ['path', { d: 'M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H19a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1H6.5a1 1 0 0 1 0-5H20' }]
    ],
    'star': [
      ['polygon', { points: '12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2' }]
    ],
    'check-circle-2': [
      ['circle', { cx: '12', cy: '12', r: '10' }],
      ['path', { d: 'm9 12 2 2 4-4' }]
    ],
    'check': [
      ['polyline', { points: '20 6 9 17 4 12' }]
    ],
    'shield-check': [
      ['path', { d: 'M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.8 17 5 19 5a1 1 0 0 1 1 1z' }],
      ['path', { d: 'm9 12 2 2 4-4' }]
    ],
    'chevron-down': [
      ['polyline', { points: '6 9 12 15 18 9' }]
    ],
    'chevron-right': [
      ['polyline', { points: '9 18 15 12 9 6' }]
    ]
  };

  function createIcons() {
    const elements = document.querySelectorAll('[data-lucide]');
    elements.forEach(el => {
      const name = el.getAttribute('data-lucide');
      const def = iconDefinitions[name];
      if (!def) return;

      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      const size = el.getAttribute('size') || el.getAttribute('width') || '24';
      const width = el.getAttribute('width') || size;
      const height = el.getAttribute('height') || size;
      const fill = el.getAttribute('fill') || 'none';
      const stroke = el.getAttribute('stroke') || 'currentColor';
      const strokeWidth = el.getAttribute('stroke-width') || '2';

      svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
      svg.setAttribute('width', width);
      svg.setAttribute('height', height);
      svg.setAttribute('viewBox', '0 0 24 24');
      svg.setAttribute('fill', fill);
      svg.setAttribute('stroke', stroke);
      svg.setAttribute('stroke-width', strokeWidth);
      svg.setAttribute('stroke-linecap', 'round');
      svg.setAttribute('stroke-linejoin', 'round');

      const existingClass = el.getAttribute('class') || '';
      svg.setAttribute('class', `lucide lucide-${name} ${existingClass}`.trim());

      Array.from(el.attributes).forEach(attr => {
        if (!['data-lucide', 'class', 'size', 'width', 'height', 'fill', 'stroke', 'stroke-width'].includes(attr.name)) {
          svg.setAttribute(attr.name, attr.value);
        }
      });

      def.forEach(([tag, attrs]) => {
        const child = document.createElementNS('http://www.w3.org/2000/svg', tag);
        Object.entries(attrs).forEach(([k, v]) => child.setAttribute(k, v));
        svg.appendChild(child);
      });

      if (el.parentNode) {
        el.parentNode.replaceChild(svg, el);
      }
    });
  }

  const lucide = {
    icons: iconDefinitions,
    createIcons: createIcons
  };

  global.lucide = lucide;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', createIcons);
  } else {
    createIcons();
  }
})(typeof window !== 'undefined' ? window : this);
